body.content:
上一节课你学会了用 `createElement` 动态创建{{term:元素}}。但这里有一个棘手的问题：

```js
// 页面初始有 3 张卡片，每张绑定了点击事件
let cards = document.querySelectorAll(".card");
cards.forEach(function(card) {
  card.addEventListener("click", function() {
    alert("点击了卡片！");
  });
});
// 后来动态添加了一张新卡片
let newCard = document.createElement("div");
newCard.classList.add("card");
listEl.appendChild(newCard);
// ❌ 新卡片没有点击事件！因为 addEventListener 运行时它还不存在
```

这是一个很常见的 bug：**动态添加的{{term:元素}}不会自动继承之前绑定的{{term:事件}}**。

不分别给每张卡片绑{{term:事件}}，而是**给包含所有卡片的父容器绑一个{{term:事件}}**。当子{{term:元素}}被点击时，{{term:事件}}会"冒泡"到父容器：

```js
// 给父容器绑定事件（只绑定一次！）
listEl.addEventListener("click", function(event) {
  // event.target 是实际被点击的元素
  // closest(".card") 向上查找最近的 .card 容器
  let card = event.target.closest(".card");
  if (card) {
    // 找到了！说明点击的是某张卡片
    card.classList.toggle("highlight");
  }
});
// 之后动态添加的卡片也会自动响应，因为事件绑在父容器上！
```

这就是**{{term:事件}}委托**——把{{term:事件}}交给父容器代理，不管子{{term:元素}}是初始就有还是后来加的，都能响应。

starter.css:
h1 {
  text-align: center;
  color: #8B2E2E;
}
#cardList {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 400px;
  margin: 16px auto;
}
.card {
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 10px;
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: all 0.3s;
}
.card.liked {
  background: #FFF0F0;
  border-color: #C94545;
}
.card-info h3 {
  margin: 0 0 4px 0;
  color: #8B2E2E;
  font-size: 16px;
}
.tag {
  color: #C9A96E;
  font-size: 12px;
  font-weight: 600;
}
.like-btn {
  background: transparent;
  border: 1px solid #D4C5A9;
  border-radius: 8px;
  padding: 6px 14px;
  cursor: pointer;
  font-size: 14px;
  color: #6B5A4E;
  transition: all 0.2s;
  flex-shrink: 0;
}
.like-btn:hover {
  background: #C94545;
  color: white;
  border-color: #C94545;
}
.card.liked .like-btn {
  background: #C94545;
  color: white;
  border-color: #C94545;
}
.add-bar {
  text-align: center;
  margin-top: 16px;
}
#addBtn {
  padding: 10px 24px;
  background: #8B2E2E;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 15px;
}
#addBtn:hover {
  background: #C94545;
}

starter.js:
// ❌ 当前方式：用 forEach 逐个绑定事件
// 问题：动态添加的卡片不会自动获得点击事件
// 任务：改成事件委托——只在 #cardList 上绑定一个事件
let likeBtns = document.querySelectorAll(".like-btn");
likeBtns.forEach(function(btn) {
  btn.addEventListener("click", function() {
    let card = btn.closest(".card");
    card.classList.toggle("liked");
    if (card.classList.contains("liked")) {
      btn.textContent = "❤ 已收藏";
    } else {
      btn.textContent = "❤ 收藏";
    }
  });
});
// 添加随机曲目（新卡片不会有事件！这就是你要修复的问题）
document.querySelector("#addBtn").addEventListener("click", function() {
  let pieces = [
    { name: "G弦上的咏叹调", period: "巴洛克" },
    { name: "第40号交响曲", period: "古典主义" },
    { name: "夜曲 Op.9 No.2", period: "浪漫主义" }
  ];
  let p = pieces[Math.floor(Math.random() * pieces.length)];
  
  let listEl = document.querySelector("#cardList");
  let card = document.createElement("div");
  card.classList.add("card");
  card.innerHTML = '<div class="card-info"><h3>' + p.name + '</h3><span class="tag">' + p.period + '</span></div><button class="like-btn">❤ 收藏</button>';
  listEl.appendChild(card);
});
